import type { LineId } from './mockData';

export interface StopTimeEntry {
  stopName: string;
  time: string; // "05:15"
  timeMinutes: number; // minuty od północy
}

export interface ScheduledTrip {
  id: string;
  lineId: LineId;
  directionIdx: 0 | 1;
  dayType: 'weekday' | 'saturday' | 'sunday';
  tripNumber: number;
  startTime: string;
  startTimeMinutes: number;
  endTime: string;
  endTimeMinutes: number;
  stops: StopTimeEntry[];
}

export interface OfficialDirectionData {
  name: string;
  destination: string;
  stops: string[];
  stopDepartures: Record<string, {
    weekday: string[];
    saturday: string[];
    sunday: string[];
  }>;
  trips: {
    weekday: ScheduledTrip[];
    saturday: ScheduledTrip[];
    sunday: ScheduledTrip[];
  };
}

export interface OfficialLineData {
  lineId: LineId;
  validFrom: string;
  directions: [OfficialDirectionData, OfficialDirectionData];
}

