/**
 * Zwraca oficjalne godziny odjazdów z wybranego przystanku z PDF ZDiTM
 */
export function getOfficialStopDepartures(
  lineId: LineId,
  stopName: string,
  directionIdx: 0 | 1 = 0,
): { weekday: string[]; saturday: string[]; sunday: string[] } {
  const line = OFFICIAL_TIMETABLES[lineId];
  if (!line) return { weekday: [], saturday: [], sunday: [] };
  const dir = line.directions[directionIdx] || line.directions[0];
  if (!dir) return { weekday: [], saturday: [], sunday: [] };

  // Bezpośrednie dopasowanie nazwy
  if (dir.stopDepartures[stopName]) {
    return dir.stopDepartures[stopName];
  }

  // Dopasowanie case-insensitive lub częściowe (np. "Plac Dworcowy" vs "PLAC DWORCOWY 01")
  const key = Object.keys(dir.stopDepartures).find(
    (k) =>
      k.toLowerCase() === stopName.toLowerCase() ||
      k.toLowerCase().includes(stopName.toLowerCase()) ||
      stopName.toLowerCase().includes(k.toLowerCase())
  );

  if (key && dir.stopDepartures[key]) {
    return dir.stopDepartures[key];
  }

  return { weekday: [], saturday: [], sunday: [] };
}

/**
 * Zwraca wszystkie zaplanowane kursy danej linii w danym dniu
 */
export function getScheduledTripsForLine(
  lineId: LineId,
  dayType: 'weekday' | 'saturday' | 'sunday',
  directionIdx?: 0 | 1,
): ScheduledTrip[] {
  const line = OFFICIAL_TIMETABLES[lineId];
  if (!line) return [];

  const trips: ScheduledTrip[] = [];
  if (directionIdx === undefined || directionIdx === 0) {
    trips.push(...line.directions[0].trips[dayType]);
  }
  if (directionIdx === undefined || directionIdx === 1) {
    trips.push(...line.directions[1].trips[dayType]);
  }

  return trips.sort((a, b) => a.startTimeMinutes - b.startTimeMinutes);
}
